ST.xhtml:
parts.u1(
    number := 1,
    operatorStatus_ref := statuses.operatorStatus,
    activityStatus_ref := statuses.activityStatus,
    services_ref := parts.services);
parts.u2(
    number := 2,
    operatorStatus_ref := statuses.operatorStatus,
    activityStatus_ref := statuses.activityStatus,
    services_ref := parts.services);
parts.u3(
    number := 3,
    operatorStatus_ref := statuses.operatorStatus,
    activityStatus_ref := statuses.activityStatus,
    services_ref := parts.services);
parts.u4(
    number := 4,
    operatorStatus_ref := statuses.operatorStatus,
    activityStatus_ref := statuses.activityStatus,
    services_ref := parts.services);
parts.services( operatorStatus_ref := statuses.operatorStatus );
statuses.healthStatus := F_HealthStatus(
    superState := NOT(statuses.initializationStatus = InitializationStatus.shutdown),
    isGood := (parts.u1.statuses.healthStatus = HealthStatus.good) AND ((parts.u2.statuses.healthStatus = HealthStatus.good) AND ((parts.u3.statuses.healthStatus = HealthStatus.good) AND ((parts.u4.statuses.healthStatus = HealthStatus.good) AND (parts.services.statuses.healthStatus = HealthStatus.good)))),
    hasWarning := (parts.u1.statuses.healthStatus = HealthStatus.warning) OR ((parts.u2.statuses.healthStatus = HealthStatus.warning) OR ((parts.u3.statuses.healthStatus = HealthStatus.warning) OR ((parts.u4.statuses.healthStatus = HealthStatus.warning) OR (parts.services.statuses.healthStatus = HealthStatus.warning)))));
statuses.busyStatus := F_BusyStatus(
    superState := NOT(statuses.initializationStatus = InitializationStatus.shutdown),
    isBusy := (parts.u1.statuses.busyStatus = BusyStatus.busy) OR ((parts.u2.statuses.busyStatus = BusyStatus.busy) OR ((parts.u3.statuses.busyStatus = BusyStatus.busy) OR ((parts.u4.statuses.busyStatus = BusyStatus.busy) OR (parts.services.statuses.busyStatus = BusyStatus.busy)))));
processes.initialize( isEnabled := NOT(statuses.initializationStatus = InitializationStatus.initializing) );
processes.lock( isEnabled := (statuses.operatorStatus = OperatorStatus.tech) AND (statuses.initializationStatus = InitializationStatus.initialized) );
processes.unlock( isEnabled := (statuses.operatorStatus = OperatorStatus.tech) AND (statuses.initializationStatus = InitializationStatus.locked) );
processes.changeOperator( isEnabled := TRUE );
processes.verifyPassword( isEnabled := TRUE );
processes.wakeUp( isEnabled := TRUE );
processes.goToSleep( isEnabled := TRUE );
processes.emergencyClose( isEnabled := NOT((parts.u1.parts.dome.parts.shutter.statuses.apertureStatus = ApertureStatus.closed) AND ((parts.u1.parts.dome.parts.shutter.statuses.apertureStatus = ApertureStatus.closed) AND ((parts.u1.parts.dome.parts.shutter.statuses.apertureStatus = ApertureStatus.closed) AND (parts.u1.parts.dome.parts.shutter.statuses.apertureStatus = ApertureStatus.closed)))) );
processes.point( isEnabled := parts.u1.processes.point.isEnabled OR (parts.u2.processes.point.isEnabled OR (parts.u3.processes.point.isEnabled OR parts.u4.processes.point.isEnabled)) );
processes.openDomes( isEnabled := parts.u1.parts.dome.parts.shutter.processes.open.isEnabled OR (parts.u2.parts.dome.parts.shutter.processes.open.isEnabled OR (parts.u3.parts.dome.parts.shutter.processes.open.isEnabled OR parts.u4.parts.dome.parts.shutter.processes.open.isEnabled)) );
processes.closeDomes( isEnabled := parts.u1.parts.dome.parts.shutter.processes.close.isEnabled OR (parts.u2.parts.dome.parts.shutter.processes.close.isEnabled OR (parts.u3.parts.dome.parts.shutter.processes.close.isEnabled OR parts.u4.parts.dome.parts.shutter.processes.close.isEnabled)) );
processes.stopDomes( isEnabled := parts.u1.parts.dome.parts.shutter.processes.stop.isEnabled OR (parts.u2.parts.dome.parts.shutter.processes.stop.isEnabled OR (parts.u3.parts.dome.parts.shutter.processes.stop.isEnabled OR parts.u4.parts.dome.parts.shutter.processes.stop.isEnabled)) );

IF do_request THEN
    do_request_result := request(
    alpha := set.alpha,
    delta := set.delta,
    u1 := set.u1,
    u2 := set.u2,
    u3 := set.u3,
    u4 := set.u4);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.alpha := alpha;
THIS^.get.delta := delta;
THIS^.get.u1 := u1;
THIS^.get.u2 := u2;
THIS^.get.u3 := u3;
THIS^.get.u4 := u4;
THIS^.statuses.busyStatus := BusyStatus.busy;
THIS^.statuses.healthStatus := HealthStatus.good;

IF THIS^.statuses.enabledStatus = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        alpha := alpha,
        delta := delta,
        u1 := u1,
        u2 := u2,
        u3 := u3,
        u4 := u4);
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request(
    u1 := set.u1,
    u2 := set.u2,
    u3 := set.u3,
    u4 := set.u4);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.u1 := u1;
THIS^.get.u2 := u2;
THIS^.get.u3 := u3;
THIS^.get.u4 := u4;
THIS^.statuses.busyStatus := BusyStatus.busy;
THIS^.statuses.healthStatus := HealthStatus.good;

IF THIS^.statuses.enabledStatus = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        u1 := u1,
        u2 := u2,
        u3 := u3,
        u4 := u4);
ELSE
    request := RequestResults.REJECTED;
END_IF;
